// Package harness installs Wingman Spec into a project for the coding agents: it renders the commands and
// subagents of harness/ for Cursor, Claude Code and Codex, copies the bundled skills,
// keeps the AGENTS.md block current and writes the .wingman-spec/bin shim the generated files call.
package harness

import (
	"bufio"
	"fmt"
	"io/fs"
	"path"
	"regexp"
	"slices"
	"strings"
)

// Names are the harnesses `init --harness` accepts, in install order.
var Names = []string{"cursor", "claude", "codex"}

// File is one generated file: its path relative to the project and its content.
type File struct {
	Path string
	Data []byte
}

const mark = "generated by wingman-spec init from harness/"

var (
	partialRE = regexp.MustCompile(`^\{\{> ([a-z0-9-]+)\}\}$`)
	// Codex runs project commands as skills, invoked as $name instead of /name.
	codexRE = regexp.MustCompile("(^|[\\s(`\"'])/(spec-[a-z]+)")
)

func codexify(s string) string { return codexRE.ReplaceAllString(s, "$1$$$2") }

// source is one commands/ or agents/ file: its front matter keys and its body with the partials expanded.
type source struct {
	name string
	fm   map[string]string
	body string
}

func parse(src fs.FS, p string) (source, error) {
	b, err := fs.ReadFile(src, p)
	if err != nil {
		return source{}, err
	}
	s := source{name: strings.TrimSuffix(path.Base(p), ".md"), fm: map[string]string{}}
	lines := strings.Split(string(b), "\n")
	i := 0
	if len(lines) > 0 && lines[0] == "---" {
		for i = 1; i < len(lines) && lines[i] != "---"; i++ {
			if k, v, ok := strings.Cut(lines[i], ": "); ok {
				if _, seen := s.fm[k]; !seen {
					s.fm[k] = strings.TrimSuffix(strings.TrimPrefix(v, `"`), `"`)
				}
			}
		}
		i++
	}
	var out strings.Builder
	for _, l := range lines[i:] {
		if m := partialRE.FindStringSubmatch(l); m != nil {
			pb, err := fs.ReadFile(src, "partials/"+m[1]+".md")
			if err != nil {
				return source{}, fmt.Errorf("%s: missing partial %s", p, m[1])
			}
			sc := bufio.NewScanner(strings.NewReader(string(pb)))
			for sc.Scan() {
				out.WriteString(sc.Text() + "\n")
			}
			continue
		}
		out.WriteString(l + "\n")
	}
	// the source's last newline split off an empty last element; a body ends with exactly the source's newlines
	s.body = strings.TrimSuffix(out.String(), "\n")
	return s, nil
}

func sources(src fs.FS, dir string) ([]source, error) {
	names, err := fs.Glob(src, dir+"/*.md")
	if err != nil {
		return nil, err
	}
	slices.Sort(names)
	var out []source
	for _, n := range names {
		s, err := parse(src, n)
		if err != nil {
			return nil, err
		}
		out = append(out, s)
	}
	return out, nil
}

// Render generates one harness's commands and subagents from src (the harness/ tree). Same input, same bytes.
//
//	harness  commands                                       subagents
//	cursor   .cursor/commands/<n>.md                        .cursor/agents/<a>.md (model: inherit)
//	claude   .claude/commands/<n>.md                        .claude/agents/<a>.md
//	codex    .agents/skills/<n>/SKILL.md (invoked as $<n>)  .codex/agents/<a>.toml
//
// An agent with `readonly: true` gets `readonly: true` in Cursor, `tools: Read, Grep, Glob` in Claude Code and
// `[features] shell_tool = false` in Codex.
func Render(src fs.FS, h string) ([]File, error) {
	if !slices.Contains(Names, h) {
		return nil, fmt.Errorf("unknown harness %q (cursor, claude, codex)", h)
	}
	cmds, err := sources(src, "commands")
	if err != nil {
		return nil, err
	}
	agents, err := sources(src, "agents")
	if err != nil {
		return nil, err
	}
	var out []File
	add := func(p, s string) { out = append(out, File{p, []byte(s)}) }
	for _, c := range cmds {
		d, hint := c.fm["description"], c.fm["argument-hint"]
		if d == "" {
			return nil, fmt.Errorf("harness/commands/%s.md has no description", c.name)
		}
		note := "<!-- " + mark + "commands/" + c.name + ".md; edits are overwritten on update -->\n"
		switch h {
		case "cursor":
			add(".cursor/commands/"+c.name+".md", "---\ndescription: \""+d+"\"\n---\n"+note+c.body)
		case "claude":
			fm := "---\ndescription: \"" + d + "\"\n"
			if hint != "" {
				fm += "argument-hint: \"" + hint + "\"\n"
			}
			add(".claude/commands/"+c.name+".md", fm+"---\n"+note+c.body)
		case "codex":
			s := "---\nname: " + c.name + "\ndescription: \"" + d + "\"\n---\n" + note
			if hint != "" {
				s += "Invoke as `$" + c.name + " " + hint + "`.\n\n"
			}
			add(".agents/skills/"+c.name+"/SKILL.md", s+codexify(c.body))
		}
	}
	for _, a := range agents {
		n, d, ro := a.fm["name"], a.fm["description"], a.fm["readonly"] == "true"
		if n == "" || d == "" {
			return nil, fmt.Errorf("harness/agents/%s.md needs name and description", a.name)
		}
		note := "<!-- " + mark + "agents/" + n + ".md; edits are overwritten on update -->\n"
		switch h {
		case "cursor":
			s := "---\nname: " + n + "\ndescription: \"" + d + "\"\nmodel: inherit\n"
			if ro {
				s += "readonly: true\n"
			}
			add(".cursor/agents/"+n+".md", s+"---\n"+note+a.body)
		case "claude":
			s := "---\nname: " + n + "\ndescription: \"" + d + "\"\n"
			if ro {
				s += "tools: Read, Grep, Glob\n"
			}
			add(".claude/agents/"+n+".md", s+"---\n"+note+a.body)
		case "codex":
			b := strings.TrimRight(codexify(a.body), "\n")
			if strings.Contains(b, "'''") {
				return nil, fmt.Errorf("harness/agents/%s.md contains ''' and cannot be a TOML literal string", a.name)
			}
			s := "name = \"" + n + "\"\ndescription = \"" + codexify(d) + "\"\n# " + mark + "agents/" + n + ".md; edits are overwritten on update\n" +
				"developer_instructions = '''\n" + b + "\n'''\n"
			if ro {
				s += "\n[features]\nshell_tool = false\n"
			}
			add(".codex/agents/"+n+".toml", s)
		}
	}
	return out, nil
}
